// Event labels
haloText(panelB, 'Beginning', bX + 5, brkY + 22, 11, '#333');
haloText(panelB, 'event', bX + 5, brkY + 35, 11, '#333');
haloText(panelB, 'Ending', bX + 2 * (snapW + snapGap) + 5, brkY + 22, 11, '#333');
haloText(panelB, 'event', bX + 2 * (snapW + snapGap) + 5, brkY + 35, 11, '#333');

// Observer on Earth
var obsX = bX + (snapW + snapGap) + snapW / 2, obsY = brkY + 55;
panelB.polygon((obsX - 70) + ',' + (obsY + 45) + ' ' + (obsX + 70) + ',' + (obsY + 45) + ' ' + (obsX + 90) + ',' + (obsY + 62) + ' ' + (obsX - 90) + ',' + (obsY + 62))
  .fill('#d4c5a0').stroke({ color: '#b0a080', width: 1 });
makeCircle(panelB, obsX, obsY, 7, '#8fbc8f', '#556b2f', 1);
panelB.rect(obsX - 6, obsY + 7, 12, 26).rx(4).fill('#8fbc8f').stroke({ color: '#556b2f', width: 1 });
