haloText(panelB, 'Observer', obsX - 85, obsY + 15, 11, '#333');
haloText(panelB, 'on Earth', obsX - 85, obsY + 28, 11, '#333');
panelB.path('M ' + (obsX - 40) + ',' + (obsY + 20) + ' Q ' + (obsX - 25) + ',' + (obsY + 15) + ' ' + (obsX - 10) + ',' + (obsY + 10))
  .fill('none').stroke({ color: '#333', width: 1 });

// Clock Δt
var ckBx = obsX + 35, ckBy = obsY + 12;
makeCircle(panelB, ckBx, ckBy, 14, '#fff', '#333', 1.5);
panelB.line(ckBx, ckBy, ckBx, ckBy - 10).stroke({ color: '#333', width: 1.5 });
