// PANEL (c) — Triangle, bottom center
// ═══════════════════════════════════════════════════════════
var panelC = draw.group();
var triCx = 500, triBaseY = 720, triH = 130;

function drawTriangle() {
  panelC.clear();
  var hb = getL(state.v);
  var leftX = triCx - hb, rightX = triCx + hb;
  var topY = triBaseY - triH;

  // Triangle sides (purple diagonals)
  panelC.line(leftX, triBaseY, triCx, topY).stroke({ color: '#7b5ea7', width: 2.5 });
  panelC.line(triCx, topY, rightX, triBaseY).stroke({ color: '#7b5ea7', width: 2.5 });
  // Base (black)
  panelC.line(leftX, triBaseY, rightX, triBaseY).stroke({ color: '#333', width: 1.5 });
  // Vertical altitude D
  panelC.line(triCx, topY, triCx, triBaseY).stroke({ color: '#333', width: 1.5 });

  // Arrowheads on diagonals
  var m1x = (leftX + triCx) / 2, m1y = (triBaseY + topY) / 2;
  var m2x = (triCx + rightX) / 2, m2y = (topY + triBaseY) / 2;
  panelC.polygon((m1x - 4) + ',' + (m1y + 4) + ' ' + m1x + ',' + (m1y - 4) + ' ' + (m1x + 4) + ',' + (m1y + 4)).fill('#7b5ea7');
  panelC.polygon((m2x - 4) + ',' + (m2y - 4) + ' ' + m2x + ',' + (m2y + 4) + ' ' + (m2x + 4) + ',' + (m2y - 4)).fill('#7b5ea7');

