  haloText(panelC, 's', m2x + 8, m2y - 12, 14, '#7b5ea7', { style: 'italic' });
  haloText(panelC, 'D', triCx + 7, (topY + triBaseY) / 2 - 8, 14, '#333', { style: 'italic' });
