  haloText(panelC, 'L', triCx + hb / 2 - 4, triBaseY + 10, 13, '#333', { style: 'italic' });

  // Equation above
  haloText(panelC, 's = √(D² + L²)', triCx - 55, topY - 28, 14, '#333');

  // Event markers (small circles at vertices)
  var evColors = ['#f5c542', '#7ec8e3', '#e74c3c'];
  var evPos = [[leftX, triBaseY], [triCx, topY], [rightX, triBaseY]];
